-- Vietnam deep-dive ES/DE/FR translations (completing 291). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Modelo dual — validación en tiempo real o reporte el mismo día (Dirección General de Tributación)', 'Esta página de análisis refleja la orientación pública de la GDT y las noticias del sector disponibles en agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La práctica de aplicación de sanciones y los detalles de los umbrales siguen evolucionando — confirme los requisitos actuales directamente con la Dirección General de Tributación o con su proveedor de integración antes de basarse en ellos.', 'El marco de facturación electrónica de Vietnam se estableció mediante el Decreto 123/2020/ND-CP en diciembre de 2020, se puso a prueba en seis provincias y ciudades, entre ellas Hanói y Ciudad Ho Chi Minh, a partir de noviembre de 2021, y se volvió obligatorio en todo el país el 1 de julio de 2022, momento en el que las facturas en papel dejaron de tener validez legal a efectos del IVA. El Decreto 70/2025/ND-CP, en vigor desde junio de 2025, amplió después el mandato a los grandes hogares empresariales y a los proveedores extranjeros de comercio electrónico.', 'Las facturas se elaboran en XML estructurado según las normas técnicas de la Dirección General de Tributación (GDT). Se exige firma digital en toda factura, salvo las emitidas desde cajas registradoras POS, que quedan exentas de la firma pero generan en su lugar un código QR/fiscal único.', 'El mandato cubre las ventas nacionales B2B, B2C minoristas, B2G y de exportación de todas las empresas registradas desde julio de 2022, e incorpora a los hogares empresariales y autónomos con una facturación anual superior a 1.000 millones de VND para la facturación electrónica por POS desde junio de 2025, junto con los sectores de cara al consumidor (comercio minorista, hostelería, transporte, servicios personales) sin importar su facturación. Las importaciones no están sujetas a la emisión de facturas electrónicas por parte del importador.', 'Cumplir implica integrar una solución de facturación electrónica, determinar cuál de los dos modelos de transmisión se aplica a sus facturas y, en el caso de los hogares empresariales y los sectores de cara al consumidor, comprobar si les aplica el umbral de facturación electrónica por POS.', 'El régimen sancionador de Vietnam, reestructurado por el Decreto 310/2025/ND-CP a partir del 16 de enero de 2026, gradúa las multas según el número de facturas infractoras detectadas en un período de inspección, en lugar de una cifra fija o porcentual: una única factura tardía conlleva una multa modesta, pero la misma infracción repetida en 100 o más facturas conlleva una multa decenas de veces mayor.', 'El mandato de facturación electrónica de Vietnam es obligatorio en todo el país desde el 1 de julio de 2022, con dos modelos de transmisión que coexisten: validación en tiempo real con un código de la Dirección General de Tributación (GDT), o reporte el mismo día sin código. El Decreto 70/2025/ND-CP amplió la cobertura en junio de 2025 a los grandes hogares empresariales (facturación de 1.000 millones de VND o más) y a los proveedores extranjeros de comercio electrónico, y un régimen sancionador reestructurado y graduado según el número de infracciones entró en vigor en enero de 2026.', '🇻🇳' FROM countries WHERE name_en = 'Vietnam';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Duales Modell — Echtzeit-Freigabe oder tagesgleiche Meldung (Steuerbehörde GDT)', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der GDT und Branchenberichte mit Stand August 2026 wider und dient der allgemeinen Information, nicht der Rechts- oder Steuerberatung. Die Durchsetzungspraxis bei Sanktionen und die Schwellenwerte entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der Generaldirektion für Steuern (GDT) oder Ihrem Integrationsanbieter, bevor Sie sich darauf verlassen.', 'Vietnams E-Invoicing-Rahmen wurde im Dezember 2020 durch das Dekret 123/2020/ND-CP geschaffen, ab November 2021 in sechs Provinzen und Städten – darunter Hanoi und Ho-Chi-Minh-Stadt – erprobt und wurde am 1. Juli 2022 landesweit verpflichtend, als Papierrechnungen ihre umsatzsteuerliche Gültigkeit verloren. Das ab Juni 2025 geltende Dekret 70/2025/ND-CP weitete die Pflicht anschließend auf große Gewerbehaushalte und ausländische E-Commerce-Anbieter aus.', 'Rechnungen werden als strukturiertes XML nach den technischen Standards der Generaldirektion für Steuern (GDT) erstellt. Eine digitale Signatur ist für jede Rechnung vorgeschrieben, außer für Rechnungen aus POS-Registrierkassen, die von der Signaturpflicht befreit sind, stattdessen aber einen eindeutigen QR-/Steuercode erzeugen.', 'Die Pflicht umfasst inländisches B2B, B2C-Einzelhandel, B2G und Exportumsätze für alle registrierten Unternehmen seit Juli 2022; Gewerbehaushalte und Einzelunternehmer mit einem Jahresumsatz über 1 Milliarde VND sind seit Juni 2025 zusätzlich für POS-E-Invoicing erfasst, ebenso wie verbraucherorientierte Branchen (Einzelhandel, Gastgewerbe, Verkehr, persönliche Dienstleistungen) unabhängig vom Umsatz. Importe unterliegen keiner Pflicht zur Rechnungsstellung durch den Importeur.', 'Um konform zu sein, müssen Sie eine E-Invoicing-Lösung integrieren, ermitteln, welches der beiden Übermittlungsmodelle für Ihre Rechnungen gilt, und — für Gewerbehaushalte und verbraucherorientierte Branchen — prüfen, ob der POS-E-Invoicing-Schwellenwert für Sie gilt.', 'Vietnams Sanktionsrahmen, der durch das ab 16. Januar 2026 geltende Dekret 310/2025/ND-CP neu gefasst wurde, staffelt die Bußgelder nach der Anzahl der innerhalb eines Prüfungszeitraums festgestellten Verstöße statt nach einem festen oder prozentualen Betrag — eine einzelne verspätete Rechnung zieht ein moderates Bußgeld nach sich, dieselbe Pflichtverletzung bei 100 oder mehr Rechnungen jedoch ein um ein Vielfaches höheres.', 'Vietnams E-Invoicing-Pflicht gilt seit dem 1. Juli 2022 landesweit, mit zwei parallel bestehenden Übermittlungsmodellen — Echtzeit-Freigabe mit einem Code der Generaldirektion für Steuern (GDT) oder tagesgleiche Meldung ohne Code. Das Dekret 70/2025/ND-CP weitete die Erfassung im Juni 2025 auf große Gewerbehaushalte (Umsatz ab 1 Milliarde VND) und ausländische E-Commerce-Anbieter aus, und ein neu gestaffelter, nach Verstoßzahl gestufter Sanktionsrahmen trat im Januar 2026 in Kraft.', '🇻🇳' FROM countries WHERE name_en = 'Vietnam';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Modèle double — validation en temps réel ou déclaration le jour même (Direction générale de la fiscalité)', 'Cette page d''analyse reflète les indications publiques de la GDT et les informations sectorielles disponibles en août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les pratiques d''application des sanctions et les détails des seuils continuent d''évoluer — confirmez les exigences actuelles directement auprès de la Direction générale de la fiscalité ou de votre prestataire d''intégration avant de vous y fier.', 'Le cadre de facturation électronique du Viêt Nam a été établi par le décret 123/2020/ND-CP en décembre 2020, expérimenté dans six provinces et villes, dont Hanoï et Hô-Chi-Minh-Ville, à partir de novembre 2021, puis est devenu obligatoire dans tout le pays le 1er juillet 2022, date à laquelle les factures papier ont perdu toute validité légale au regard de la TVA. Le décret 70/2025/ND-CP, entré en vigueur en juin 2025, a ensuite étendu l''obligation aux grands foyers d''entreprise et aux fournisseurs étrangers de commerce électronique.', 'Les factures sont établies en XML structuré selon les normes techniques de la Direction générale de la fiscalité (GDT). Une signature électronique est exigée pour chaque facture, sauf celles émises par des caisses enregistreuses POS, dispensées de signature mais générant à la place un code QR/fiscal unique.', 'L''obligation couvre les ventes B2B domestiques, B2C au détail, B2G et à l''exportation pour toutes les entreprises enregistrées depuis juillet 2022 ; les foyers d''entreprise et entrepreneurs individuels dont le chiffre d''affaires annuel dépasse 1 milliard de VND entrent dans le champ de la facturation électronique par POS depuis juin 2025, de même que les secteurs en contact direct avec les consommateurs (commerce de détail, hôtellerie, transport, services à la personne), quel que soit leur chiffre d''affaires. Les importations ne sont pas soumises à une obligation de facturation électronique pour l''importateur.', 'Se mettre en conformité suppose d''intégrer une solution de facturation électronique, de déterminer lequel des deux modèles de transmission s''applique à vos factures et, pour les foyers d''entreprise et les secteurs en contact avec les consommateurs, de vérifier si le seuil de facturation électronique par POS vous concerne.', 'Le régime de sanctions du Viêt Nam, restructuré par le décret 310/2025/ND-CP à compter du 16 janvier 2026, échelonne les amendes selon le nombre de factures en infraction constatées lors d''une période de contrôle plutôt que selon un montant fixe ou un pourcentage : une seule facture tardive entraîne une amende modeste, mais la même infraction répétée sur 100 factures ou plus entraîne une amende des dizaines de fois supérieure.', 'L''obligation de facturation électronique du Viêt Nam est en vigueur dans tout le pays depuis le 1er juillet 2022, avec deux modèles de transmission qui coexistent — validation en temps réel avec un code de la Direction générale de la fiscalité (GDT), ou déclaration le jour même sans code. Le décret 70/2025/ND-CP a étendu la couverture en juin 2025 aux grands foyers d''entreprise (chiffre d''affaires d''au moins 1 milliard de VND) et aux fournisseurs étrangers de commerce électronique, et un régime de sanctions restructuré, échelonné selon le nombre d''infractions, est entré en vigueur en janvier 2026.', '🇻🇳' FROM countries WHERE name_en = 'Vietnam';

