INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato de elaboración", "XML estructurado, según las normas técnicas de la GDT"], ["Firma digital", "Obligatoria, salvo en las facturas de cajas registradoras POS"], ["Elemento de verificación", "Código emitido por la GDT (validación en tiempo real) o un registro de transmisión el mismo día (modelo de reporte)"], ["Base legal", "Decreto 123/2020/ND-CP, modificado por el Decreto 70/2025/ND-CP; orientación de la Circular 78/2021/TT-BTC"]]', 'Toda factura es XML sin importar el modelo de transmisión aplicable: los dos modelos difieren en cuándo y cómo la GDT ve los datos, no en el formato de la propia factura.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Erstellungsformat", "Strukturiertes XML nach den technischen Standards der GDT"], ["Digitale Signatur", "Vorgeschrieben, außer bei Rechnungen aus POS-Registrierkassen"], ["Prüfnachweis", "Von der GDT ausgestellter Code (Echtzeit-Freigabe) oder ein tagesgleicher Übermittlungsnachweis (Meldemodell)"], ["Rechtsgrundlage", "Dekret 123/2020/ND-CP, geändert durch Dekret 70/2025/ND-CP; Richtlinie Circular 78/2021/TT-BTC"]]', 'Jede Rechnung liegt als XML vor, unabhängig davon, welches Übermittlungsmodell gilt — die beiden Modelle unterscheiden sich darin, wann und wie die GDT die Daten sieht, nicht im Format der Rechnung selbst.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format de création", "XML structuré, selon les normes techniques de la GDT"], ["Signature électronique", "Obligatoire, sauf pour les factures émises par des caisses enregistreuses POS"], ["Élément de vérification", "Code délivré par la GDT (validation en temps réel) ou un enregistrement de transmission le jour même (modèle de déclaration)"], ["Base juridique", "Décret 123/2020/ND-CP, modifié par le décret 70/2025/ND-CP ; circulaire d''application 78/2021/TT-BTC"]]', 'Chaque facture est en XML quel que soit le modèle de transmission applicable — les deux modèles diffèrent par le moment et la manière dont la GDT reçoit les données, pas par le format de la facture elle-même.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identidad del contribuyente", "Número de identificación fiscal vietnamita (MST)"], ["Vías de acceso", "Sistema propio, un proveedor de servicios certificado o el propio portal de facturación electrónica de la GDT"], ["Plataforma de transmisión", "Sistema centralizado de la Dirección General de Tributación (GDT)"], ["Proveedores extranjeros", "Los proveedores digitales/de comercio electrónico sin establecimiento permanente en Vietnam pueden registrarse directamente desde junio de 2025"]]', 'La vía de registro para proveedores extranjeros es nueva con el Decreto 70/2025: antes, un proveedor digital no residente no tenía ninguna vía directa para emitir una factura de IVA vietnamita conforme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-Identität", "Vietnamesische Steueridentifikationsnummer (MST)"], ["Zugangswege", "Eigenes System, ein zertifizierter Dienstleister oder das eigene E-Invoice-Portal der GDT"], ["Übermittlungsplattform", "Zentralisiertes System der Generaldirektion für Steuern (GDT)"], ["Ausländische Anbieter", "Digital-/E-Commerce-Anbieter ohne dauerhafte Niederlassung in Vietnam können sich seit Juni 2025 direkt registrieren"]]', 'Der Registrierungsweg für ausländische Anbieter ist neu mit Dekret 70/2025 — zuvor hatte ein gebietsfremder digitaler Anbieter überhaupt keinen direkten Weg, eine konforme vietnamesische Umsatzsteuerrechnung auszustellen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identité du contribuable", "Numéro d''identification fiscale vietnamien (MST)"], ["Voies d''accès", "Système interne, un prestataire certifié, ou le portail de facturation électronique de la GDT lui-même"], ["Plateforme de transmission", "Système centralisé de la Direction générale de la fiscalité (GDT)"], ["Fournisseurs étrangers", "Les fournisseurs numériques/de commerce électronique sans établissement permanent au Viêt Nam peuvent s''enregistrer directement depuis juin 2025"]]', 'La voie d''enregistrement pour les fournisseurs étrangers est nouvelle avec le décret 70/2025 — auparavant, un fournisseur numérique non-résident n''avait aucun moyen direct d''émettre une facture de TVA vietnamienne conforme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio y archivo', '[["Datos de las partes", "Números de identificación fiscal del vendedor y del comprador"], ["Tipos de factura", "Facturas de IVA o facturas de venta, según el método fiscal del vendedor"], ["Facturas POS", "Transmisión en tiempo real, firma exenta, se genera un código QR/fiscal único"], ["Período de conservación", "10 años, en su forma electrónica original (XML) con las firmas digitales intactas"]]', 'Diez años es un plazo de conservación más largo que el que exigen la mayoría de los países de este seguimiento: planifique la infraestructura de archivo en consecuencia, ya sea propia o con un proveedor certificado (el almacenamiento en el extranjero está permitido bajo ciertas condiciones de seguridad de los datos).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalt & Archivierung', '[["Parteidaten", "Steueridentifikationsnummern von Verkäufer und Käufer"], ["Rechnungsarten", "Umsatzsteuerrechnungen oder Verkaufsrechnungen, je nach Besteuerungsmethode des Verkäufers"], ["POS-Rechnungen", "Echtzeitübermittlung, Signatur entfällt, eindeutiger QR-/Steuercode wird erzeugt"], ["Aufbewahrungsfrist", "10 Jahre, im ursprünglichen elektronischen (XML-)Format mit intakten digitalen Signaturen"]]', 'Zehn Jahre sind eine längere Aufbewahrungspflicht, als die meisten Länder in diesem Tracker verlangen — planen Sie Ihre Archivinfrastruktur entsprechend, ob intern oder bei einem zertifizierten Anbieter (Speicherung im Ausland ist unter datenschutzrechtlichen Bedingungen zulässig).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire et archivage', '[["Données des parties", "Numéros d''identification fiscale du vendeur et de l''acheteur"], ["Types de facture", "Factures de TVA ou factures de vente, selon le régime fiscal du vendeur"], ["Factures POS", "Transmission en temps réel, signature non requise, code QR/fiscal unique généré"], ["Durée de conservation", "10 ans, sous forme électronique originale (XML) avec les signatures électroniques intactes"]]', 'Dix ans est une obligation de conservation plus longue que celle exigée par la plupart des pays de ce suivi — prévoyez une infrastructure d''archivage en conséquence, qu''elle soit interne ou confiée à un prestataire certifié (le stockage à l''étranger est autorisé sous certaines conditions de sécurité des données).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'Modelo 1 — validación en tiempo real (con código de la GDT)', 'Cuando una factura se emite bajo el modelo con código, sigue esta secuencia:', 'Nada llega al comprador hasta que la GDT ha emitido el código: un auténtico modelo de validación, con la misma forma que Jordania e Israel en otras partes de este seguimiento.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Modell 1 — Echtzeit-Freigabe (mit GDT-Code)', 'Wird eine Rechnung nach dem Code-Modell ausgestellt, durchläuft sie diese Abfolge:', 'Nichts erreicht den Käufer, bevor die GDT den Code ausgestellt hat — ein echtes Freigabemodell, in derselben Form wie Jordanien und Israel an anderer Stelle dieses Trackers.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Modèle 1 — validation en temps réel (avec code de la GDT)', 'Lorsqu''une facture est émise selon le modèle avec code, elle suit cette séquence :', 'Rien ne parvient à l''acheteur tant que la GDT n''a pas délivré le code — un véritable modèle de validation, de la même forme que la Jordanie et Israël ailleurs dans ce suivi.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 0;

