INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Codierte Rechnung an den Käufer geliefert' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 0 AND ls.sort_order = 3;
