INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'Modelo 2 — reporte el mismo día (sin código)', 'Cuando una factura se emite bajo el modelo sin código, sigue en cambio esta secuencia:', 'Este es el flujo más parecido al modelo posterior a la emisión de Corea del Sur en otras partes de este seguimiento: la factura es válida al entregarse, y el reporte a la autoridad tributaria es una obligación paralela que vence a más tardar el mismo día, no una condición previa para su validez.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Modell 2 — tagesgleiche Meldung (ohne Code)', 'Wird eine Rechnung nach dem codelosen Modell ausgestellt, durchläuft sie stattdessen diese Abfolge:', 'Dies ist der Ablauf, der dem Post-Ausstellungsmodell Südkoreas an anderer Stelle dieses Trackers am ähnlichsten ist — die Rechnung ist bei Lieferung gültig, und die Meldung an die Steuerbehörde ist eine parallele Pflicht, die spätestens am selben Tag fällig wird, keine Voraussetzung für die Gültigkeit.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Modèle 2 — déclaration le jour même (sans code)', 'Lorsqu''une facture est émise selon le modèle sans code, elle suit à la place cette séquence :', 'C''est le flux le plus proche du modèle post-émission de la Corée du Sud ailleurs dans ce suivi — la facture est valide dès sa remise, et la déclaration à l''administration fiscale est une obligation parallèle exigible au plus tard le jour même, non une condition préalable à sa validité.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 1;

