INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'La GDT recoupe les données déclarées' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Vietnam' AND lc.sort_order = 1 AND ls.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Quién está dentro del ámbito, y desde cuándo', '[["Todas las empresas registradas", "Obligatorio desde el 1 de julio de 2022"], ["Hogares empresariales/autónomos con facturación ≥ 1.000 millones de VND", "Facturación electrónica por POS obligatoria desde junio de 2025"], ["Sectores de cara al consumidor (comercio minorista, hostelería, transporte, servicios personales)", "Facturación electrónica por POS obligatoria sin importar la facturación, desde junio de 2025"], ["Proveedores extranjeros digitales/de comercio electrónico", "Pueden registrarse directamente desde junio de 2025 (voluntario)"]]', 'La norma para los sectores de cara al consumidor es una excepción real al umbral basado en la facturación de Vietnam: un pequeño restaurante o una peluquería están dentro del ámbito incluso muy por debajo de los 1.000 millones de VND de facturación anual.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Wer betroffen ist, und seit wann', '[["Alle registrierten Unternehmen", "Verpflichtend seit 1. Juli 2022"], ["Gewerbehaushalte/Einzelunternehmer mit Umsatz ≥ 1 Mrd. VND", "POS-E-Invoicing verpflichtend seit Juni 2025"], ["Verbraucherorientierte Branchen (Einzelhandel, Gastgewerbe, Verkehr, persönliche Dienstleistungen)", "POS-E-Invoicing verpflichtend unabhängig vom Umsatz, seit Juni 2025"], ["Ausländische digitale/E-Commerce-Anbieter", "Können sich seit Juni 2025 direkt registrieren (freiwillig)"]]', 'Die Regel für verbraucherorientierte Branchen ist eine echte Ausnahme von Vietnams sonst umsatzbasierter Schwelle — ein kleines Restaurant oder ein Friseursalon ist selbst weit unter 1 Milliarde VND Jahresumsatz erfasst.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Qui est concerné, et depuis quand', '[["Toutes les entreprises enregistrées", "Obligatoire depuis le 1er juillet 2022"], ["Foyers d''entreprise/indépendants avec un chiffre d''affaires ≥ 1 milliard de VND", "Facturation électronique par POS obligatoire depuis juin 2025"], ["Secteurs en contact avec les consommateurs (commerce de détail, hôtellerie, transport, services à la personne)", "Facturation électronique par POS obligatoire quel que soit le chiffre d''affaires, depuis juin 2025"], ["Fournisseurs étrangers numériques/de commerce électronique", "Peuvent s''enregistrer directement depuis juin 2025 (facultatif)"]]', 'La règle applicable aux secteurs en contact avec les consommateurs est une véritable exception au seuil vietnamien autrement basé sur le chiffre d''affaires — un petit restaurant ou un salon de coiffure est concerné même bien en deçà d''1 milliard de VND de chiffre d''affaires annuel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Qué está cubierto', '[["B2B nacional", "Cubierto"], ["B2C minorista", "Cubierto"], ["B2G", "Cubierto"], ["Exportaciones", "Cubierto: la factura debe emitirse a más tardar el siguiente día hábil tras el despacho aduanero"], ["Importaciones", "No cubierto: el importador no tiene obligación de emitir factura electrónica"]]', 'El alcance de Vietnam es realmente amplio: ventas nacionales y transfronterizas, contratos minoristas y públicos por igual, con las importaciones como única exclusión explícita, ya que la obligación recae en el vendedor, no en el comprador.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was abgedeckt ist', '[["Inländisches B2B", "Abgedeckt"], ["B2C-Einzelhandel", "Abgedeckt"], ["B2G", "Abgedeckt"], ["Exporte", "Abgedeckt — Rechnung fällig spätestens am nächsten Werktag nach der Zollabfertigung"], ["Importe", "Nicht abgedeckt — keine Pflicht zur Rechnungsstellung durch den Importeur"]]', 'Vietnams Anwendungsbereich ist wirklich weit gefasst — inländische wie grenzüberschreitende Umsätze, Einzelhandel und öffentliche Aufträge gleichermaßen —, wobei Importe die einzige ausdrückliche Ausnahme bilden, da die Pflicht beim Verkäufer und nicht beim Käufer liegt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est couvert', '[["B2B domestique", "Couvert"], ["B2C au détail", "Couvert"], ["B2G", "Couvert"], ["Exportations", "Couvert — facture due au plus tard le jour ouvrable suivant le dédouanement"], ["Importations", "Non couvert — aucune obligation de facturation électronique pour l''importateur"]]', 'Le champ d''application du Viêt Nam est réellement large — ventes domestiques et transfrontalières, contrats de détail et publics confondus —, les importations étant la seule exception explicite, l''obligation incombant au vendeur et non à l''acheteur.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

