INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Falta de emisión de factura — 1 factura infractora', '1 – 2 millones de VND', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Vietnam' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Keine Rechnung ausgestellt — 1 verstoßende Rechnung', '1 – 2 Mio. VND', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Vietnam' AND pr.sort_order = 2;
