INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Falta de emisión de factura — 100 o más facturas infractoras', '60 – 80 millones de VND', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Vietnam' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Keine Rechnung ausgestellt — 100 oder mehr verstoßende Rechnungen', '60 – 80 Mio. VND', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Vietnam' AND pr.sort_order = 3;
