INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📊 Las sanciones se gradúan según el volumen, no solo la gravedad', NULL, NULL, 'El régimen sancionador de Vietnam se gradúa según el número de facturas infractoras detectadas en un período de inspección, no según una cifra fija o porcentual: una única factura tardía o faltante conlleva una multa modesta, mientras que la misma infracción en 100 o más facturas conlleva una multa decenas de veces mayor. Varias infracciones el mismo día cuentan como una sola sanción al nivel más alto aplicable, no como una sanción por factura.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📊 Sanktionen richten sich nach dem Umfang, nicht nur nach der Schwere', NULL, NULL, 'Vietnams Bußgeldkatalog staffelt sich nach der Anzahl der innerhalb eines Prüfungszeitraums festgestellten verstoßenden Rechnungen, nicht nach einem festen oder prozentualen Betrag — eine einzelne verspätete oder fehlende Rechnung zieht ein moderates Bußgeld nach sich, dieselbe Pflichtverletzung bei 100 oder mehr Rechnungen jedoch ein um ein Vielfaches höheres. Mehrere Verstöße am selben Tag zählen als eine einzige Sanktion auf der höchsten anwendbaren Stufe, nicht als eine Sanktion pro Rechnung.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📊 Les sanctions dépendent du volume, pas seulement de la gravité', NULL, NULL, 'Le barème des amendes du Viêt Nam s''échelonne selon le nombre de factures en infraction constatées lors d''une période de contrôle, et non selon un montant fixe ou un pourcentage — une seule facture tardive ou manquante entraîne une amende modeste, tandis que la même infraction répétée sur 100 factures ou plus entraîne une amende des dizaines de fois supérieure. Plusieurs infractions le même jour comptent comme une seule sanction au niveau le plus élevé applicable, et non comme une sanction par facture.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Dos categorías de factura, dos tablas de sanciones', NULL, NULL, 'Las ventas generadoras de ingresos (bienes y servicios) tienen una tabla de multas separada, generalmente más alta, que las facturas no comerciales o de uso interno: promociones, muestras, regalos, consumo interno y operaciones de préstamo tienen su propio régimen, más leve. La tabla anterior refleja la categoría de ventas generadoras de ingresos.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Zwei Rechnungskategorien, zwei Bußgeldtabellen', NULL, NULL, 'Umsatzgenerierende Verkäufe (Waren und Dienstleistungen) unterliegen einer eigenen, in der Regel höheren Bußgeldtabelle als nichtkommerzielle Rechnungen oder Rechnungen zum internen Gebrauch — Werbeaktionen, Muster, Geschenke, interner Verbrauch und Verleih-/Ausleihvorgänge folgen einem eigenen, milderen Katalog. Die obige Tabelle bildet die umsatzgenerierende Kategorie ab.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Deux catégories de factures, deux barèmes de sanctions', NULL, NULL, 'Les ventes génératrices de revenus (biens et services) relèvent d''un barème d''amendes distinct, généralement plus élevé, que les factures non commerciales ou à usage interne — promotions, échantillons, cadeaux, consommation interne et opérations de prêt/emprunt relèvent d''un barème propre, plus léger. Le tableau ci-dessus reflète la catégorie génératrice de revenus.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📅 Un régimen más estricto y reestructurado desde enero de 2026', NULL, NULL, 'El Decreto 310/2025/ND-CP sustituyó la anterior estructura de multa fija por la tabla graduada según el número de infracciones anterior, en vigor desde el 16 de enero de 2026: el mandato de facturación electrónica en sí no cambió, pero sí el coste de incumplirlo a gran escala.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📅 Ein verschärfter, neu gefasster Rahmen seit Januar 2026', NULL, NULL, 'Das Dekret 310/2025/ND-CP ersetzte die bisherige feste Bußgeldstruktur durch die oben gezeigte, nach Verstoßzahl gestaffelte Tabelle, gültig ab dem 16. Januar 2026 — die zugrunde liegende E-Invoicing-Pflicht selbst änderte sich nicht, wohl aber die Kosten, sie im großen Maßstab zu verfehlen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📅 Un cadre durci et restructuré depuis janvier 2026', NULL, NULL, 'Le décret 310/2025/ND-CP a remplacé l''ancienne structure d''amende fixe par le barème échelonné selon le nombre d''infractions ci-dessus, en vigueur depuis le 16 janvier 2026 — l''obligation de facturation électronique elle-même n''a pas changé, mais le coût d''un manquement à grande échelle, si.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Vietnam' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su solución de facturación electrónica está integrada', 'Toda empresa registrada necesita un sistema que envíe las facturas a la GDT -- API directa, software propio o un proveedor de servicios certificado --, ya que las facturas en papel no tienen validez legal desde julio de 2022.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihre E-Invoicing-Lösung integriert ist', 'Jedes registrierte Unternehmen benötigt ein System, das Rechnungen an die GDT weiterleitet -- direkte API, eigene Software oder ein zertifizierter Dienstleister --, da Papierrechnungen seit Juli 2022 keine rechtliche Gültigkeit mehr haben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez que votre solution de facturation électronique est intégrée', 'Chaque entreprise enregistrée a besoin d''un système acheminant les factures vers la GDT -- API directe, logiciel interne ou prestataire certifié --, les factures papier n''ayant plus aucune validité légale depuis juillet 2022.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Determine qué modelo de transmisión se aplica a sus facturas', 'Averigüe si sus facturas necesitan un código emitido por la GDT antes de la entrega (validación en tiempo real) o el reporte el mismo día sin código, y configure sus sistemas para el flujo correcto.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestimmen Sie, welches Übermittlungsmodell für Ihre Rechnungen gilt', 'Klären Sie, ob Ihre Rechnungen vor der Lieferung einen von der GDT ausgestellten Code benötigen (Echtzeit-Freigabe) oder der tagesgleichen Meldung ohne Code unterliegen, und richten Sie Ihre Systeme für den richtigen Ablauf ein.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déterminez quel modèle de transmission s''applique à vos factures', 'Déterminez si vos factures nécessitent un code délivré par la GDT avant la livraison (validation en temps réel) ou relèvent de la déclaration le jour même sans code, et configurez vos systèmes en conséquence.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Hogares empresariales y autónomos: comprueben el umbral de 1.000 millones de VND', 'Si su facturación anual alcanza o supera los 1.000 millones de VND, registren una caja registradora POS conectada a la GDT, y comprueben también la norma de los sectores de cara al consumidor, que se aplica sin importar la facturación.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Gewerbehaushalte und Einzelunternehmer: prüfen Sie die Schwelle von 1 Milliarde VND', 'Erreicht oder überschreitet Ihr Jahresumsatz 1 Milliarde VND, registrieren Sie eine mit der GDT verbundene POS-Registrierkasse — prüfen Sie zudem die Regel für verbraucherorientierte Branchen, die unabhängig vom Umsatz gilt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Foyers d''entreprise et indépendants : vérifiez le seuil d''1 milliard de VND', 'Si votre chiffre d''affaires annuel atteint ou dépasse 1 milliard de VND, enregistrez une caisse POS connectée à la GDT — et vérifiez également la règle applicable aux secteurs en contact avec les consommateurs, qui s''applique quel que soit le chiffre d''affaires.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Proveedores digitales extranjeros: consideren el registro directo de facturas de IVA', 'Desde junio de 2025, los proveedores extranjeros de comercio electrónico y de servicios digitales sin establecimiento en Vietnam pueden registrarse para emitir facturas de IVA vietnamitas directamente, en lugar de depender de un intermediario local.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ausländische digitale Anbieter: erwägen Sie die direkte Registrierung für Umsatzsteuerrechnungen', 'Seit Juni 2025 können ausländische E-Commerce- und Digitaldienstanbieter ohne Niederlassung in Vietnam sich registrieren, um vietnamesische Umsatzsteuerrechnungen direkt auszustellen, statt sich auf einen lokalen Vermittler zu verlassen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Fournisseurs numériques étrangers : envisagez l''enregistrement direct pour la facturation de TVA', 'Depuis juin 2025, les fournisseurs étrangers de commerce électronique et de services numériques sans établissement au Viêt Nam peuvent s''enregistrer pour émettre directement des factures de TVA vietnamiennes plutôt que de dépendre d''un intermédiaire local.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte el momento de emisión de la factura al tipo de operación', 'Bienes: en el momento de la transferencia de la propiedad o del derecho de uso. Servicios: al finalizar el servicio. Exportaciones: a más tardar el siguiente día hábil tras el despacho aduanero. Suministros: a más tardar el día 7 del mes siguiente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Passen Sie den Rechnungsstellungszeitpunkt an die Art des Geschäfts an', 'Waren: bei Übertragung des Eigentums oder der Nutzungsrechte. Dienstleistungen: bei Abschluss. Exporte: spätestens am nächsten Werktag nach der Zollabfertigung. Versorgungsleistungen: spätestens am 7. Tag des Folgemonats.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Adaptez le moment d''émission de la facture au type d''opération', 'Biens : au transfert de propriété ou des droits d''usage. Services : à l''achèvement. Exportations : au plus tard le jour ouvrable suivant le dédouanement. Services collectifs : au plus tard le 7e jour du mois suivant.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Archiven toda factura durante 10 años en su forma XML original', 'La conservación aquí es más larga que en la mayoría de los países de este seguimiento: conserven el propio XML firmado, no solo una representación en PDF, ya sea con almacenamiento propio o con un proveedor certificado.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Archivieren Sie jede Rechnung 10 Jahre lang im ursprünglichen XML-Format', 'Die Aufbewahrungsfrist ist hier länger als in den meisten Ländern dieses Trackers — bewahren Sie das signierte XML selbst auf, nicht nur eine PDF-Darstellung, ob intern oder bei einem zertifizierten Anbieter.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Archivez chaque facture pendant 10 ans sous sa forme XML d''origine', 'La durée de conservation est ici plus longue que dans la plupart des pays couverts par ce suivi — conservez le XML signé lui-même, pas seulement un rendu PDF, que ce soit en interne ou chez un prestataire certifié.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Vietnam' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Dirección General de Tributación (GDT)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Vietnam' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Generaldirektion für Steuern (GDT)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Vietnam' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Direction générale de la fiscalité (GDT)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Vietnam' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Sistema de consulta de facturas (tra cứu hóa đơn)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Vietnam' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Rechnungsabfragesystem (tra cứu hóa đơn)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Vietnam' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Système de consultation des factures (tra cứu hóa đơn)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Vietnam' AND dp.sort_order = 1;
